function Cameras(p:WorkspaceProps){return <div className="stack"><div className="row between wrap"><Chip tone="gray">Device Configuration Unavailable</Chip><span className="metadata">No fabricated video feeds</span></div><div className="camera-grid">{['Camera Slot 01','Camera Slot 02','Camera Slot 03','Camera Slot 04'].map((s,i)=><button className="camera-frame" key={s} onClick={()=>p.detail(s,<div className="stack"><Camera size={38}/><h3>Feed Unavailable</h3><p>This is a camera-layout slot, not a claim of a configured device. Provider, camera, NVR and access-event details require authorized configuration.</p></div>)}><header><span>{s} · Layout Preview</span><span>UNAVAILABLE</span></header><Camera size={42} strokeWidth={1.2}/><strong>No Authorized Feed</strong><small>Provider Configuration Required</small></button>)}</div><Panel title="Devices & Access Events"><p>No configured camera, NVR or access-event records are connected to this preview.</p></Panel></div>}
function Rbac(p:WorkspaceProps){const [preview,setPreview]=useState('manager');const person=personas.find(x=>x.id===preview)!;const selected=pages.filter(x=>['eggs','finance','employees','profile','myday','rbac'].includes(x.id));return <div className="project-layout"><Panel title="Effective Access Matrix" description="Sample rule evaluation; backend authorization remains authoritative"><div className="permission-matrix"><div className="matrix-head">Workspace</div>{['Read','Write','Farm Scope','Result'].map(x=><div className="matrix-head" key={x}>{x}</div>)}{selected.map(page=><React.Fragment key={page.id}><div>{page.title}</div><div>{page.permission.some(k=>has(person,k))?<Check className="grant" size={17}/>:<X size={16}/>}</div><div>{page.write&&has(person,page.write)?<Check className="grant" size={17}/>:<span>—</span>}</div><div>{page.farm?(person.farm?'Assigned':'Missing'):'N/A'}</div><div>{canView(person,page)?'Visible':'Hidden'}</div></React.Fragment>)}</div></Panel><Panel title="Review A Sample Permission Set"><SelectField label="Sample Access Preview" value={preview} onChange={setPreview} options={personas.map(x=>({value:x.id,label:x.label}))}/><div className="mt"><h3>{person.label}</h3><p style={{fontSize:'.875rem',marginTop:12}}>The result combines explicit sample permissions, self-service availability and farm scope.</p><div className="auth-state mt">Owner protection and provisional lifecycle are preserved as backend responsibilities. This matrix does not edit a role.</div></div></Panel></div>}
function Settings(p:WorkspaceProps){const [tab,setTab]=useState('Appearance'),[unit,setUnit]=useState('c'),[pending,setPending]=useState(false);return <div className="configuration-layout"><aside className="configuration-nav">{['Appearance','Motion & Weather','Portal Context','Authentication'].map(t=><button key={t} className={t===tab?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</aside><Panel title={tab} description="Configuration scope and persistence remain explicit">{tab==='Appearance'?<><div className="theme-grid">{themes.map(([id,title,color])=><button className={`theme-card ${p.theme===id?'active':''}`} key={id} onClick={()=>{p.setTheme(id);setPending(true)}}><span className="theme-swatch" style={{background:color}}/><small>{title}</small></button>)}</div><p className="form-note mt">Ten accent previews. Theme V10’s complete assets, behavior and settings contract are preserved for integration; this is not a replacement engine.</p></>:tab==='Motion & Weather'?<><label className="setting-row"><div><strong>Reduce Motion</strong><p>Use a calmer interaction setting.</p></div><Switch checked={p.reduced} onCheckedChange={v=>{p.setReduced(v);setPending(true)}}/></label><div className="mt"><SelectField label="Weather Unit" value={unit} onChange={v=>{setUnit(v);setPending(true)}} options={[{value:'c',label:'Celsius'},{value:'f',label:'Fahrenheit'},{value:'auto',label:'Automatic'}]}/></div></>:tab==='Portal Context'?<dl className="identity-facts">{[['Scope','Current Sample Workspace'],['Business Time Zone','Africa/Lagos · WAT'],['Production Version','Not Connected'],['Persistence','No Backend Writes']].map(([l,v])=><div key={l}><dt>{l}</dt><dd>{v}</dd></div>)}</dl>:<div className="stack"><Shield size={32}/><h3>Existing Daenem Identity Providers</h3><p>Local, Google and Microsoft sign-in and signup are controlled by the existing backend. Client secrets and provider configuration are never exposed here.</p><Chip tone="gray">Read-only Design Context</Chip></div>}<hr className="rule"/><div className="row between wrap"><span className="metadata">{pending?'Sample changes pending':'No pending sample changes'}</span><Btn primary onClick={()=>{setPending(false);toast.success('Sample Preferences Applied',{description:'Preview session only. No settings API was called.'})}}>Apply To Preview</Btn></div></Panel></div>}
function Logs(p:WorkspaceProps){const [filter,setFilter]=useState('All');const logs=[['09:42:11','INFO','Sample request completed · source: portal'],['09:41:58','WARN','Sample provider unavailable · no live service status'],['09:41:10','INFO','Sample permission evaluation · scope resolved'],['09:40:33','ERROR','Sample synchronization failure · review evidence'],['09:39:50','INFO','Sample session lifecycle event · no private token']];return <div className="stack"><Lens items={['All','INFO','WARN','ERROR']} value={filter} onChange={setFilter}/><section className="terminal-panel"><header className="terminal-toolbar"><span>PORTAL / SAMPLE LOG STREAM</span><span>No Live Connection</span></header><div className="terminal-lines">{logs.filter(r=>filter==='All'||r[1]===filter).map((r,i)=><div className="log-line" key={i}><span className="log-time">{r[0]}</span><span style={{color:r[1]==='ERROR'?'#f0b1a0':r[1]==='WARN'?'#dfca80':'#a9cba6'}}>{r[1]}</span><p>{r[2]}</p></div>)}</div></section><Panel title="Correlation Details"><p>Select severity to narrow the sample stream. Actual source, correlation IDs, actor scope and details require the authorized diagnostics service.</p></Panel></div>}
function Diagnostics(p:WorkspaceProps){return <div className="project-layout"><Panel title="Service Dependency Checks" description="No live health claims"><RecordList items={['Portal API','Authentication','Weather Provider','Notification Delivery','Storage / Synchronization'].map(title=>({title,detail:'No diagnostic result connected',status:'Unavailable',icon:<CloudOff size={18}/>}))} onOpen={i=>p.detail('Diagnostic Evidence',<p>No live diagnostic request was made. The existing authorized diagnostics endpoint must provide timestamps, results and evidence for each check.</p>)}/></Panel><Panel className="dark-panel" title="Evidence, Before Confidence"><Activity size={38}/><p className="mt">An unavailable dependency is not a healthy one. This surface reserves status, timing and source fields for verified results.</p><hr className="rule" style={{borderColor:'#42664f'}}/><Chip tone="gray">Monitoring Not Connected</Chip></Panel></div>}
function Monitoring(p:WorkspaceProps){return <div className="stack"><div className="grid2">{['Request Latency','Error Rate'].map((title,i)=><Panel key={title} title={title} description={i?'Percent · Selected Period':'Milliseconds · Selected Period'}><div className="empty-chart"><Activity size={35} style={{margin:'0 auto 15px'}}/><h3>No Monitoring Observations</h3><p style={{fontSize:'.875rem',marginTop:10}}>A live signal is required before drawing a chart.</p></div></Panel>)}</div><Panel title="Service Status History"><DataTable headers={['Service','Current State','Last Observation','History']} rows={[["Portal API","Unavailable","Not Connected","Not Available"],["Weather Provider","Unavailable","Not Connected","Not Available"],["Synchronization","Unavailable","Not Connected","Not Available"]]}/></Panel></div>}
